<template><AppShell title="我的兑换" back><view class="pad"><StateView :loading="loading" :error="error" :count="items.length" title="还没有兑换记录" description="兑换或抽中实物后，可在这里填写地址和查看物流" @retry="load" /><button class="ui-button order-card card" v-for="item in items" :key="item.id" @click="go('rewards/order',{id:item.id})"><view class="row between"><text class="muted tiny">{{item.source==='DRAW'?'活动奖品':'积分兑换'}} · {{date(item.createdAt)}}</text><text class="tag">{{rewardStatus[item.status]}}</text></view><view class="row section"><image v-if="rewardImage(item.image)" :src="rewardImage(item.image)" mode="aspectFill" /><view class="stack flex-1"><text class="bold">{{item.title}}</text><text class="muted tiny">{{item.pointsSpent>0?item.pointsSpent+' 积分':'抽奖获得'}}</text></view><text>›</text></view></button><button v-if="items.length<total" class="ui-button btn outline" @click="more">加载更多</button></view></AppShell></template>
<script setup>import {watch} from 'vue';import {onShow,onReachBottom} from '@dcloudio/uni-app';import AppShell from '../../components/AppShell.vue';import StateView from '../../components/StateView.vue';import {requireLogin,go,date,session} from '../../lib/api';import {rewardStatus,rewardImage} from '../../lib/rewards';import {useList} from '../../lib/useList';const {items,total,loading,error,load,more}=useList('/boost/rewards/orders',()=>({}));watch(()=>session.token,()=>{items.value=[];total.value=0;error.value=''},{flush:'sync'});onShow(()=>{if(requireLogin())load()});onReachBottom(more)</script>
<style scoped>.order-card{display:block;width:100%;text-align:left;margin-bottom:12px}.order-card image{width:60px;height:60px;border-radius:8px}.order-card .bold{overflow-wrap:anywhere}</style>
